#!/usr/bin/env python3
"""Post-process N64Recomp RecompiledFuncs for Rogue Squadron.

VENDORED COPY (s4648): generated by scratch/s4648/make_vendored.py from
../N64Recomp/fixup_game_funcs.py. Usage: fixup_game_funcs_vendored.py <RecompiledFuncs dir>
(or RS64_FIXUP_BASE=...); refuses the live tree unless RS64_FIXUP_ALLOW_LIVE=1.
Adds a post-flow stage reproducing the live-only patches (tools/apply_s*.py
replay in a sandbox + s4648 backports); see scratch/s4648/classification.md.

Fixes three classes of invalid C the recompiler emits:
1. Writes to $zero ("    0 = expr;") -> commented out (discard).
2. fake_func_* bodies with gotos to labels that don't exist in that function -> neutered to __builtin_trap().
3. Real functions with undeclared-label gotos -> reported for manual review (not auto-fixed).

Also re-applies the durable hand patches (audio-engine gate stores, jr-$t9
return idiom) and the ~150 session-added guard/instrument patches below.

NOT idempotent per patch: most patches are ADDITIVE — their anchor text
survives in the output, so a second run on the same generated files silently
duplicates guard blocks (observed s250/s260/s272; breadcrumb grep counts
literally double) or hard-breaks the build (label/declaration redefinition,
both documented in PORTING-STATE.md). The run-level sentinel check below
refuses the second run. The contract: clear RecompiledFuncs/ and regenerate
(make_elf.py -> N64Recomp) before EVERY invocation — N64Recomp skips files
that already exist on disk, so an uncleared regen is not a regen.

2026-08-04 review note: the ~100 older guard patches are file-scoped but not
function-scoped; if overlay re-chunking ever makes same-file anchor collisions
possible, backport the BREADCRUMB10+ function-slice idiom to them.
"""
import os, re, sys, pathlib

# s4648: s2190 valued<->0u round trip (see post-flow stage at end of file).
_S2190_VALUED = re.compile(
    r"(rs64_m5_writer_parity\('[BHWD]', 0x[0-9A-F]{8}u, U32\((?:[^()]|\((?:[^()]|\([^()]*\))*\))*\)), "
    r"U32\((?:[^()]|\((?:[^()]|\([^()]*\))*\))*\)\); /\* PATCH: s2190 m5 scalar \*/")


def _s4648_s2190_zero(text):
    """Valued s2190 scalar calls -> live 0u form.

    Returns (text, pairs): pairs is the ordered list of (zero_line, original_line)
    for every s2190 scalar line, so _s4648_s2190_unzero can restore them by order
    even when callers insert other lines in between."""
    pairs = []
    out = []
    for line in text.splitlines(True):
        if "PATCH: s2190 m5 scalar" in line:
            z = _S2190_VALUED.sub(r"\1, 0u); /* PATCH: s2190 m5 scalar */", line)
            pairs.append((z, line))
            line = z
        out.append(line)
    return "".join(out), pairs


def _s4648_s2190_unzero(text, pairs):
    it = iter(pairs)
    out = []
    for line in text.splitlines(True):
        if "PATCH: s2190 m5 scalar" in line:
            z, orig = next(it)
            if z != line:
                raise RuntimeError(f"s4648 s2190 round-trip mismatch: {line.strip()[:120]}")
            line = orig
        out.append(line)
    if next(it, None) is not None:
        raise RuntimeError("s4648 s2190 round-trip: lines removed")
    return "".join(out)



# s4648 vendored: output tree comes from argv[1] or RS64_FIXUP_BASE (no default).
_RS64_LIVE = pathlib.Path("/Users/williambuckley/Documents/Tools/N64Recomp/RecompiledFuncs").resolve()
_rs64_base_arg = (sys.argv[1] if len(sys.argv) > 1 else os.environ.get("RS64_FIXUP_BASE", ""))
if not _rs64_base_arg:
    sys.exit("usage: fixup_game_funcs_vendored.py <RecompiledFuncs dir>  (or RS64_FIXUP_BASE=...)")
base = pathlib.Path(_rs64_base_arg).resolve()
if base == _RS64_LIVE and os.environ.get("RS64_FIXUP_ALLOW_LIVE") != "1":
    sys.exit("refusing to patch the live RecompiledFuncs tree without RS64_FIXUP_ALLOW_LIVE=1")
if not (base / "funcs_0.c").exists():
    sys.exit(f"{base}: no funcs_0.c (not a RecompiledFuncs tree)")

def apply_s4339_c88c_fields():
    path = base / "funcs_27.c"
    text = path.read_text()
    marker = "PATCH: s4339 C88C source/branch witness"
    if marker in text:
        return "s4339 C88C source/branch witness already present"
    decl = (
        "extern void rs64_filter_voice_c88c_field_probe(uint8_t* rdram, uint32_t s0, "
        "uint32_t s1, uint32_t branch_selector);\n"
    )
    anchor = (
        "    rs64_filter_voice_c88c_descriptor_probe(U32(ctx->r4), U32(ctx->r5), "
        "U32(ctx->r6), U32(ctx->r7)); /* PATCH: s4332 C88C descriptor witness */\n"
    )
    if text.count(anchor) != 1:
        raise RuntimeError(f"s4339 C88C descriptor anchor count={text.count(anchor)}")
    text = text.replace('#include "funcs.h"\n', '#include "funcs.h"\n' + decl, 1)
    text = text.replace(anchor, anchor + (
        "    rs64_filter_voice_c88c_field_probe(rdram, U32(ctx->r16), U32(ctx->r17), "
        "U32(ctx->r2)); /* PATCH: s4339 C88C source/branch witness */\n"
    ), 1)
    path.write_text(text)
    return "funcs_27.c: s4339 C88C source/branch witness added"

def refresh_s2028_event_sequence():
    """Refresh only the s2028 join-field spelling on a sentinel-marked tree."""
    path = base / "funcs_26.c"
    text = path.read_text()
    replacements = (
        ("static unsigned long rs64_s2028_event_total;", "static unsigned long rs64_s2028_event_seq;"),
        ("unsigned long seq = ++rs64_s2028_event_total;", "unsigned long event_seq = ++rs64_s2028_event_seq;"),
        ("row=%lu seq=%lu thr=%d", "row=%lu event_seq=%lu thr=%d"),
        ("row, seq, rogue_current_thread_id(rdram),", "row, event_seq, rogue_current_thread_id(rdram),"),
    )
    for old, new in replacements:
        count = text.count(old)
        if count != 1:
            raise RuntimeError(f"s2028 refresh anchor count={count}: {old}")
        text = text.replace(old, new, 1)
    path.write_text(text)
    print("funcs_26.c: s2028 event sequence field refreshed x4")

def apply_s3500_s3501_m5_selector_witnesses(text, p):
    """Retain the selector caller/pre-call witnesses across regeneration.

    These are diagnostic-only observations at the existing selector edge; they
    do not alter guest registers, control flow, or selector state.
    """
    if p.name != "funcs_24.c":
        return text, []
    messages = []
    if "PATCH: s3500 M5 selector caller" not in text:
        anchor = "    musyxBuildVoiceCommandList(rdram, ctx);\n"
        if text.count(anchor) != 1:
            raise RuntimeError(f"s3500 selector caller anchor count={text.count(anchor)}")
        decl = (
            "extern void rs64_m5_selector_caller(uint32_t caller_pc, uint32_t ra, "
            "uint32_t a0, uint32_t a1, uint32_t a2, uint32_t a3);\n"
        )
        call = (
            "    rs64_m5_selector_caller(0x80091330u, U32(ctx->r31), U32(ctx->r4), "
            "U32(ctx->r5), U32(ctx->r6), U32(ctx->r7)); "
            "/* PATCH: s3500 M5 selector caller */\n"
        )
        text = text.replace('#include "funcs.h"\n', '#include "funcs.h"\n' + decl, 1)
        text = text.replace(anchor, call + anchor, 1)
        messages.append("funcs_24.c: s3500 M5 selector caller patched x1")
    if "PATCH: s3501 M5 selector pre-call" not in text:
        a0 = "    // 0x8009131C: lw          $a0, -0x68F8($at)\n    ctx->r4 = MEM_W(ctx->r1, -0X68F8);\n"
        a1 = "    // 0x8009132C: lhu         $a1, -0x68F0($at)\n    ctx->r5 = MEM_HU(ctx->r1, -0X68F0);\n"
        if text.count(a0) != 1 or text.count(a1) != 1:
            raise RuntimeError(f"s3501 selector pre-call anchors count={text.count(a0)}/{text.count(a1)}")
        decl = (
            "extern void rs64_m5_selector_precall(uint32_t pc, uint32_t stage, "
            "uint32_t index, uint32_t address, uint32_t value, uint32_t a0, "
            "uint32_t a1, uint32_t a2, uint32_t s0, uint32_t s1);\n"
        )
        call0 = (
            "    rs64_m5_selector_precall(0x8009131Cu, 0u, U32(ctx->r2), U32(ctx->r1), "
            "U32(ctx->r4), U32(ctx->r4), U32(ctx->r5), U32(ctx->r6), U32(ctx->r16), "
            "U32(ctx->r17)); /* PATCH: s3501 M5 selector pre-call a0 */\n"
        )
        call1 = (
            "    rs64_m5_selector_precall(0x8009132Cu, 1u, U32(ctx->r2), U32(ctx->r1), "
            "U32(ctx->r5), U32(ctx->r4), U32(ctx->r5), U32(ctx->r6), U32(ctx->r16), "
            "U32(ctx->r17)); /* PATCH: s3501 M5 selector pre-call a1 */\n"
        )
        text = text.replace('#include "funcs.h"\n', '#include "funcs.h"\n' + decl, 1)
        text = text.replace(a0, a0 + call0, 1).replace(a1, a1 + call1, 1)
        messages.append("funcs_24.c: s3501 M5 selector pre-call patched x2")
    return text, messages

if os.environ.get("RS64_REFRESH_S2028") == "1":
    refresh_s2028_event_sequence()
    raise SystemExit(0)

# Run-level double-run refusal (2026-08-04). Every file this script modifies
# gets a trailing SENTINEL comment; finding one anywhere means the generated
# output was already patched, and a second pass would duplicate additive
# patches (and redefine labels/declarations, breaking the build). Regenerate
# first — with RecompiledFuncs/ cleared, since N64Recomp skips existing files.
SENTINEL = "// RS64_FIXUP_APPLIED"
SENTINEL_LINE = SENTINEL + " -- regenerate RecompiledFuncs (clear it first; N64Recomp skips existing files) before running fixup_game_funcs.py again\n"

