def _s1982_store_block(site, dest_reg, src_reg, src_off):
    last = {"sw": "s1982_last_sw", "sh": "s1982_last_sh", "init": "s1982_last_init"}[site]
    n = {"sw": "s1982_n_sw", "sh": "s1982_n_sh", "init": "s1982_n_init"}[site]
    nd = {"sw": "s1982_n_sw_drain", "sh": "s1982_n_sh_drain", "init": "s1982_n_init_drain"}[site]
    site_pc = {"sw": 0x80090B68, "sh": 0x80090C28, "init": 0x80092230}[site]
    else_unmap = ""
    if site in ("sw", "sh"):
        else_unmap = (
            "        } else {\n"
            "            extern unsigned long s1982_keyon_unmap;\n"
            "            ++s1982_keyon_unmap;\n"
        )
    return (
        f"    {{ // PATCH: s1982 keyon-w40 site={site}\n"
        "        static unsigned long n_w40 = 0;\n"
        "        if (avf_tick_en < 0) {\n"
        "            const char* a = getenv(\"ROGUESQ_LOG_ALL\");\n"
        "            const char* e = getenv(\"ROGUESQ_LOG_VI_CALLERS\");\n"
        "            avf_tick_en = ((a && *a && *a != '0') || (e && *e && *e != '0')) ? 1 : 0;\n"
        "        }\n"
        f"        unsigned dest = U32(ctx->r{dest_reg});\n"
        f"        unsigned src = U32(ADD32(ctx->r{src_reg}, {src_off}));\n"
        "        unsigned val = U32(ctx->r2);\n"
        "        unsigned base = (unsigned)MEM_W(-0X6908, S32(0X8015 << 16));\n"
        "        unsigned idx = 0xFFFFFFFFu;\n"
        "        if (base != 0 && dest >= base) {\n"
        "            unsigned off = dest - base;\n"
        "            if ((off % 136u) == 0 && (off / 136u) < 64u) idx = off / 136u;\n"
        "        }\n"
        "        unsigned after = 0xFFFFFFFFu;\n"
        "        if (dest >= 0x80000000u && (dest + 0x44u) <= 0x80800000u)\n"
        "            after = (unsigned)MEM_W(0, S32(dest + 0x40u));\n"
        "        ++n_w40;\n"
        "        extern int s1979_drain_cross_armed;\n"
        "        unsigned long ni = 0;\n"
        "        if (idx < 32u) {\n"
        f"            extern unsigned {last}[32];\n"
        f"            extern unsigned long {n}[32];\n"
        f"            extern unsigned long {nd}[32];\n"
        f"            {last}[idx] = after;\n"
        f"            ++{n}[idx];\n"
        f"            ni = {n}[idx];\n"
        f"            if (s1979_drain_cross_armed) ++{nd}[idx];\n"
        + else_unmap +
        "        }\n"
        "        if (avf_tick_en && (n_w40 <= 8 || (idx < 32u && (ni <= 4 || (ni % 50ul) == 0)) || (n_w40 % 50ul) == 0)) {\n"
        f"            fprintf(stderr, \"[keyon-w40] site={site} n=%lu idx=%u dest=0x%08X src=0x%08X val=0x%08X after=0x%08X base=0x%08X armed=%d\\n\",\n"
        "                    n_w40, idx, dest, src, val, after, base, s1979_drain_cross_armed);\n"
        "            fflush(stderr);\n"
        "        }\n"
        f"        rs64_m5_audio_event(\"keyon-w40\", 0x{site_pc:08X}u, U32(idx), U32(dest), U32(val), U32(after), U32(base), U32(src)); /* PATCH: s2327 task ordinal join */\n"
        + ("" if site != "init" else (
        "        { // PATCH: s1983 init-desc\n"
        "            static unsigned long n_id = 0;\n"
        "            ++n_id;\n"
        "            if (avf_tick_en && (n_id <= 8 || idx < 18u)) {\n"
        "                unsigned desc = U32(ctx->r5);\n"
        "                unsigned d00 = 0xFFFFFFFFu, d04 = 0xFFFFFFFFu, d08 = 0xFFFFFFFFu;\n"
        "                unsigned d0c = 0xFFFFFFFFu, d10 = 0xFFFFFFFFu, d14 = 0xFFFFFFFFu, d18 = 0xFFFFFFFFu;\n"
        "                if (desc >= 0x80000000u && (desc + 0x1Cu) <= 0x80800000u) {\n"
        "                    d00 = (unsigned)MEM_W(0, S32(desc + 0x00u));\n"
        "                    d04 = (unsigned)MEM_W(0, S32(desc + 0x04u));\n"
        "                    d08 = (unsigned)MEM_W(0, S32(desc + 0x08u));\n"
        "                    d0c = (unsigned)MEM_W(0, S32(desc + 0x0Cu));\n"
        "                    d10 = (unsigned)MEM_W(0, S32(desc + 0x10u));\n"
        "                    d14 = (unsigned)MEM_W(0, S32(desc + 0x14u));\n"
        "                    d18 = (unsigned)MEM_BU(0, S32(desc + 0x18u));\n"
        "                }\n"
                "                fprintf(stderr, \"[init-desc] n=%lu idx=%u dest=0x%08X desc=0x%08X d00=0x%08X d04=0x%08X d08=0x%08X d0c=0x%08X d10=0x%08X d14=0x%08X d18=0x%08X after=0x%08X\\n\",\n"
                "                        n_id, idx, dest, desc, d00, d04, d08, d0c, d10, d14, d18, after);\n"
                "                fflush(stderr);\n"
                "                rs64_m5_audio_event(\"init-desc\", 0x80092230u, U32(idx), U32(dest), U32(desc), U32(after), U32(d00), U32(d04)); /* PATCH: s2327 task ordinal join */\n"
                "            }\n"
        "        }\n"
        )) +
        "    }\n"
    )

def _s1982_apply_funcs24(t24):
    msgs = []
    sites = [
        ("sw", 17, 16, "0X40",
         "    rs64_probe_submit_gate_store('W', 0x80090B68u, U32(ADD32(ctx->r17, 0X40)), U32(ctx->r2));\n"
         "    MEM_W(0X40, ctx->r17) = ctx->r2;\n"
         "    // 0x80090B6C: lhu         $v0, 0x64($s0)\n"),
        ("sh", 17, 16, "0X44",
         "    rs64_probe_submit_gate_store('H', 0x80090C28u, U32(ADD32(ctx->r17, 0X40)), U32(ctx->r2));\n"
         "    MEM_H(0X40, ctx->r17) = ctx->r2;\n"
         "    // 0x80090C2C: lhu         $v0, 0x48($s0)\n"),
        ("init", 4, 5, "0X14",
         "    rs64_probe_submit_gate_store('W', 0x80092230u, U32(ADD32(ctx->r4, 0X40)), U32(ctx->r2));\n"
         "    MEM_W(0X40, ctx->r4) = ctx->r2;\n"
         "    // 0x80092234: lbu         $v0, 0x18($a1)\n"),
    ]
    for site, dest_reg, src_reg, src_off, old in sites:
        tag = f"PATCH: s1982 keyon-w40 site={site}"
        if tag in t24:
            msgs.append(f"funcs_24.c: s1982 {site} already present")
            continue
        n = t24.count(old)
        if n != 1:
            msgs.append(f"WARNING: funcs_24.c s1982 {site} count={n}")
            continue
        mem_end = old.find("\n    // ")
        if mem_end < 0:
            msgs.append(f"WARNING: funcs_24.c s1982 {site} split failed")
            continue
        stored = old[:mem_end + 1]
        rest = old[mem_end + 1:]
        t24 = t24.replace(old, stored + _s1982_store_block(site, dest_reg, src_reg, src_off) + rest, 1)
        msgs.append(f"funcs_24.c: s1982 {site} patched x1")
    return t24, msgs

