def apply_s3338_m5_callback_entry_text(text):
    """Capture registerSiCallback's incoming target and caller marker."""
    marker = "PATCH: s3338 m5 callback entry"
    if marker in text:
        return text, ["funcs_2.c: s3338 callback entry already present"], False
    anchor = (
        "RECOMP_FUNC void registerSiCallback(uint8_t* rdram, recomp_context* ctx) {\n"
        "    uint64_t hi = 0, lo = 0, result = 0;\n"
        "    int c1cs = 0;\n"
    )
    if text.count(anchor) != 1:
        raise SystemExit(f"s3338 registerSiCallback anchor count={text.count(anchor)}")
    insert = (
        anchor +
        "    { extern void rs64_m5_callback_entry_event(unsigned, unsigned, unsigned); "
        "rs64_m5_callback_entry_event(U32(ctx->r4), U32(ctx->r31), 0u); } "
        "{ extern void rs64_m5_callback_teardown_event(unsigned, unsigned, unsigned, unsigned, unsigned, unsigned, unsigned, unsigned); "
        "rs64_m5_callback_teardown_event(1u, U32(ctx->r31), U32(MEM_W(0, S32(0x8011A8A4u))), U32(MEM_W(4, S32(0x8011A8A4u))), U32(MEM_W(8, S32(0x8011A8A4u))), U32(MEM_W(12, S32(0x8011A8A4u))), 0u, 0u); } "
        "/* PATCH: s3338 m5 callback entry */\n"
    )
    return text.replace(anchor, insert, 1), ["funcs_2.c: s3338 callback entry patched x1"], True


def apply_s3341_m5_callback_pointer_store_text(text):
    """Capture the guest store that initializes the indirect callback pointer."""
    marker = "PATCH: s3341 m5 callback pointer store"
    if marker in text:
        return text, ["funcs_24.c: s3341 callback pointer store already present"], False
    anchor = (
        "    // 0x80091900: sw          $v0, -0x662C($at)\n"
        "    rs64_m5_writer_parity('W', 0x80091900u, U32(ADD32(ctx->r1, -0X662C)), U32(ctx->r2)); /* PATCH: s2190 m5 scalar */\n"
        "    rs64_probe_submit_gate_store('W', 0x80091900u, U32(ADD32(ctx->r1, -0X662C)), U32(ctx->r2));\n"
        "    MEM_W(-0X662C, ctx->r1) = ctx->r2;\n"
    )
    if text.count(anchor) != 1:
        _i = text.find("// 0x80091900: sw")
        raise SystemExit(f"s3341 callback pointer store anchor count={text.count(anchor)}\n" + text[_i-4:_i+520])
    insert = (
        "    { extern void rs64_m5_callback_writer_event(unsigned, unsigned, unsigned); "
        "rs64_m5_callback_writer_event(0x80091900u, 0u, U32(ctx->r2)); } "
        "/* PATCH: s3341 m5 callback pointer store */\n"
    )
    return text.replace(anchor, anchor + insert, 1), [
        "funcs_24.c: s3341 callback pointer store patched x1"
    ], True


def apply_s4771_m5_callback_teardown_text(text):
    """Record shutdown entry and the post-body return boundary."""
    marker = "PATCH: s4771 m5 callback teardown entry"
    return_marker = "PATCH: s4894 m5 callback teardown return"
    changed = False
    messages = []
    anchor = (
        "RECOMP_FUNC void shutdownAudioEngine(uint8_t* rdram, recomp_context* ctx) {\n"
        "    uint64_t hi = 0, lo = 0, result = 0;\n"
        "    int c1cs = 0;\n"
    )
    if text.count(anchor) != 1:
        raise SystemExit(f"s4771 shutdownAudioEngine anchor count={text.count(anchor)}")
    insert = (
        "    { extern void rs64_m5_callback_teardown_event(unsigned, unsigned, unsigned, unsigned, unsigned, unsigned, unsigned, unsigned); "
        "rs64_m5_callback_teardown_event(0u, U32(ctx->r31), U32(MEM_W(0, S32(0x8011A8A4u))), "
        "U32(MEM_W(4, S32(0x8011A8A4u))), U32(MEM_W(8, S32(0x8011A8A4u))), "
        "U32(MEM_W(12, S32(0x8011A8A4u))), 0u, 0u); } "
        f"/* {marker} */\n"
    )
    if marker not in text:
        if text.count(anchor) != 1:
            raise SystemExit(f"s4771 shutdownAudioEngine anchor count={text.count(anchor)}")
        text = text.replace(anchor, anchor + insert, 1)
        messages.append("funcs_24.c: s4771 callback teardown entry patched x1")
        changed = True
    return_anchor = (
        "    // 0x80091EAC: nop\n\n"
        "    return;\n"
    )
    if return_marker not in text:
        if text.count(return_anchor) != 1:
            raise SystemExit(f"s4894 shutdownAudioEngine return anchor count={text.count(return_anchor)}")
        return_insert = (
            "    { extern void rs64_m5_callback_teardown_event(unsigned, unsigned, unsigned, unsigned, unsigned, unsigned, unsigned, unsigned); "
            "rs64_m5_callback_teardown_event(2u, U32(ctx->r31), U32(MEM_W(0, S32(0x8011A8A4u))), "
            "U32(MEM_W(4, S32(0x8011A8A4u))), U32(MEM_W(8, S32(0x8011A8A4u))), "
            "U32(MEM_W(12, S32(0x8011A8A4u))), 0u, 0u); } "
            f"/* {return_marker} */\n"
        )
        text = text.replace(return_anchor, return_insert + return_anchor, 1)
        messages.append("funcs_24.c: s4894 callback teardown return patched x1")
        changed = True
    elif not messages:
        messages.append("funcs_24.c: s4771 callback teardown entry and s4894 return already present")
    return text, messages, changed


def apply_s3277_swapbuffer_delay_slot_text(text):
    """Move swapBufferWithViMode jal delay-slot $a0 before osViSetMode.

    ORIGIN: jal at 0x8001BB54. Hardware executes addiu $a0,$a0,-0x44 in the
    delay slot, passing copied-mode dest 0x80128C90. N64Recomp skips that
    slot via goto-after, so the call sees 0x80128CD4 (width 2), which is not
    a legitimate OSViMode pointer.
    """
    if S3277_MARK in text:
        return text, ["funcs_5.c: s3277 delay-slot $a0 already present"], False
    skip_n = text.count(S3277_OLD_SKIP)
    if skip_n == 1:
        return text.replace(S3277_OLD_SKIP, S3277_NEW_SKIP, 1), [
            "funcs_5.c: s3277 delay-slot $a0 moved before osViSetMode"
        ], True
    if skip_n != 0:
        raise RuntimeError(f"s3277 skip-goto delay-slot anchor count={skip_n}")
    if "PATCH: s803 direct VI caller probe site=0x8001BB54" not in text:
        raise RuntimeError("s3277: swapBufferWithViMode delay-slot and s803 probe both missing")
    start = text.find("PATCH: s803 direct VI caller probe site=0x8001BB54")
    window = text[start:start + 2500]
    if window.count(S3277_PROBE_CALL) != 1:
        raise RuntimeError("s3277: s803 swapBuffer probe call-site unmatched")
    patched_window = window.replace(S3277_PROBE_CALL, S3277_PROBE_PRE, 1)
    return text[:start] + patched_window + text[start + 2500:], [
        "funcs_5.c: s3277 delay-slot $a0 reinserted before osViSetMode"
    ], True


def apply_s3277_swapbuffer_delay_slot():
    target = base / "funcs_5.c"
    text, msgs, changed = apply_s3277_swapbuffer_delay_slot_text(target.read_text())
    if changed:
        target.write_text(text)
    return msgs


