def apply_s2308_m5_pcm_writer_provenance():
    marker = "PATCH: s2308 m5 PCM writer provenance"
    helper_anchor = "        rs64_m5_field348_store(width, pc, addr, value);\n    }\n"
    helper_block = (
        "    { /* PATCH: s2308 m5 PCM writer provenance */\n"
        "        static int s2308_enabled = -1;\n"
        "        if (s2308_enabled < 0) {\n"
        "            const char* e = getenv(\"ROGUESQ_LOG_M5_PCM_WRITER\");\n"
        "            const char* all = getenv(\"ROGUESQ_LOG_ALL\");\n"
        "            s2308_enabled = ((e && e[0] && e[0] != '0') ||\n"
        "                             (all && all[0] && all[0] != '0')) ? 1 : 0;\n"
        "        }\n"
        "        if (s2308_enabled) {\n"
        "            extern void rs64_m5_pcm_writer_store(char width,\n"
        "                                                  uint32_t pc,\n"
        "                                                  uint32_t addr,\n"
        "                                                  uint32_t value);\n"
        "            rs64_m5_pcm_writer_store(width, pc, addr, value);\n"
        "        }\n"
        "    }\n"
    )
    helper_changed = 0
    callsite_changed = 0
    call_re = re.compile(r'^(\s*)osAiSetNextBuffer_recomp\(rdram, ctx\);\s*$')
    jal_re = re.compile(r'^\s*//\s*0x([0-9A-Fa-f]+):\s*jal\s+0x80029E80\b')
    for p in sorted(base.glob("funcs_*.c")):
        text = p.read_text()
        if marker not in text:
            if text.count(helper_anchor) == 0:
                lines = text.splitlines(True)
                out = []
                for i, line in enumerate(lines):
                    match = call_re.match(line.rstrip("\n"))
                    if match and "PATCH: s2308 PCM callsite" not in (out[-1] if out else ""):
                        callsite = None
                        for j in range(i - 1, max(-1, i - 20), -1):
                            target = jal_re.match(lines[j].rstrip("\n"))
                            if target:
                                callsite = int(target.group(1), 16)
                                break
                        if callsite is None:
                            raise RuntimeError(f"s2308 {p.name}:{i + 1}: missing AI jal")
                        indent = match.group(1)
                        out.extend([
                            f"{indent}{{ /* PATCH: s2308 PCM callsite */\n",
                            f"{indent}    extern void rs64_m5_pcm_set_callsite(uint32_t callsite);\n",
                            f"{indent}    rs64_m5_pcm_set_callsite(0x{callsite:08X}u);\n",
                            f"{indent}}}\n",
                        ])
                        callsite_changed += 1
                    out.append(line)
                p.write_text("".join(out))
                continue
            if text.count(helper_anchor) != 1:
                raise RuntimeError(f"s2308 {p.name}: helper anchor count={text.count(helper_anchor)}")
            text = text.replace(helper_anchor, helper_anchor + helper_block, 1)
            helper_changed += 1
        lines = text.splitlines(True)
        out = []
        for i, line in enumerate(lines):
            match = call_re.match(line.rstrip("\n"))
            if match and "PATCH: s2308 PCM callsite" not in (out[-1] if out else ""):
                callsite = None
                for j in range(i - 1, max(-1, i - 20), -1):
                    target = jal_re.match(lines[j].rstrip("\n"))
                    if target:
                        callsite = int(target.group(1), 16)
                        break
                if callsite is None:
                    raise RuntimeError(f"s2308 {p.name}:{i + 1}: missing AI jal")
                indent = match.group(1)
                out.extend([
                    f"{indent}{{ /* PATCH: s2308 PCM callsite */\n",
                    f"{indent}    extern void rs64_m5_pcm_set_callsite(uint32_t callsite);\n",
                    f"{indent}    rs64_m5_pcm_set_callsite(0x{callsite:08X}u);\n",
                    f"{indent}}}\n",
                ])
                callsite_changed += 1
            out.append(line)
        p.write_text("".join(out))
    return [f"s2308 PCM writer provenance helpers patched {helper_changed} files",
            f"s2308 PCM callsites patched {callsite_changed}"]

def apply_s2506_m5_ai_table_rows():
    marker = "PATCH: s2506 M5 AI table runtime join"
    p = base / "funcs_23.c"
    text = p.read_text()
    if marker in text:
        return ["s2506 AI table rows already present"]
    root = (
        "    { /* PATCH: s2506 M5 AI table runtime join */\n"
        "        extern void rs64_m5_ai_table_row(uint32_t, uint32_t, uint32_t, uint32_t);\n"
        "        rs64_m5_ai_table_row(0u, U32(ctx->r2), U32(ctx->r2), 1u);\n"
        "    }\n"
    )
    entry = (
        "    { /* PATCH: s2506 M5 AI table runtime join */\n"
        "        extern void rs64_m5_ai_table_row(uint32_t, uint32_t, uint32_t, uint32_t);\n"
        "        rs64_m5_ai_table_row(U32(ctx->r5) - 1u,\n"
        "            U32(MEM_W(S32(0x8015 << 16), -0x6950)), U32(ctx->r2), 0u);\n"
        "    }\n"
    )
    root_anchor = "    MEM_W(0X0, ctx->r3) = ctx->r2;\nL_8008EDA8:\n"
