    # that confirms "uninitialized heap read" as the root cause rather than a
    # wrong write. Anchor is the unique guest-PC-addressed loop body
    # (0x8008F8FC-0x8008F910); file-scoped to funcs_23.c per s100's lesson.
    def _stream_node_init_patch(m):
        return m.group(1) + (
            "    { // PATCH: initSampleStreamBlockCache raw node-init diagnostic (s114) -- see fixup_game_funcs.py comment\n"
            "        static int s_stream_node_init_enabled = -1;\n"
            "        if (s_stream_node_init_enabled < 0) { const char* e = getenv(\"ROGUESQ_LOG_STREAM_NODE_INIT\"); s_stream_node_init_enabled = (e && e[0] && e[0] != '0') ? 1 : 0; }\n"
            "        if (s_stream_node_init_enabled) {\n"
            "            static int s_stream_node_init_n = 0;\n"
            "            if (s_stream_node_init_n < 32) {\n"
            "                fprintf(stderr, \"[stream-node-init] n=%d node=0x%08X raw8=0x%08X raw10=0x%08X\\n\",\n"
            "                        s_stream_node_init_n, U32(ctx->r3), MEM_W(ctx->r3, 0X8), MEM_W(ctx->r3, 0X10));\n"
            "            }\n"
            "            s_stream_node_init_n++;\n"
            "        }\n"
            "    }\n"
        )
    # (scoped, s380 backport) target: initSampleStreamBlockCache
    n = 0
    if p.name == "funcs_23.c":
        func_start_m = re.search(
            r"RECOMP_FUNC void initSampleStreamBlockCache\(uint8_t\* rdram, recomp_context\* ctx\) \{\n",
            text)
        if func_start_m:
            body_start = func_start_m.end()
            next_func_m = func_re.search(text, body_start)
            body_end = next_func_m.start() if next_func_m else len(text)
            body = text[body_start:body_end]

            new_body, n = re.subn(
                r"(L_8008F8FC:\n"
                r"    // 0x8008F8FC: sw          \$a3, 0x14\(\$v1\)\n"
                r"    MEM_W\(0X14, ctx->r3\) = ctx->r7;\n"
                r"    // 0x8008F900: addiu       \$a3, \$a3, 0x600\n"
                r"    ctx->r7 = ADD32\(ctx->r7, 0X600\);\n"
                r"    // 0x8008F904: addu        \$v0, \$t0, \$a1\n"
                r"    ctx->r2 = ADD32\(ctx->r8, ctx->r5\);\n"
                r"    // 0x8008F908: addiu       \$a1, \$a1, 0x18\n"
                r"    ctx->r5 = ADD32\(ctx->r5, 0X18\);\n"
                r"    // 0x8008F90C: sw          \$v1, -0x18\(\$v1\)\n"
                r"    MEM_W\(-0X18, ctx->r3\) = ctx->r3;\n"
                r"    // 0x8008F910: sw          \$v0, 0x4\(\$v1\)\n"
                r"    MEM_W\(0X4, ctx->r3\) = ctx->r2;\n)",
                _stream_node_init_patch,
                body)
            if n:
                text = text[:body_start] + new_body + text[body_end:]
    if n:
        changed = True
        report.append(f"{p.name}: initSampleStreamBlockCache raw node-init diagnostic patched x{n}")
        if "#include <stdio.h>" not in text:
            text = text.replace('#include "recomp.h"\n', '#include "recomp.h"\n#include <stdio.h>\n', 1)
        if "#include <stdlib.h>" not in text:
            text = text.replace('#include "recomp.h"\n', '#include "recomp.h"\n#include <stdlib.h>\n', 1)

    # musyxTriggerVoiceAttack own-entry diagnostic (s116, M3 item -1
    # continued): s105-110 instrumented only the two known STATIC callers
    # (tickAllAudioChannels, serviceVoicePoolFrame) and both read 0/0 across
    # multiple soaks that otherwise reached and survived the corrupting
    # window -- but that only proves those two specific call chains are
    # dead, not that the function itself never runs, because a chokepoint
    # instrument at the CALLER only catches calls that go through it. This
    # session (s116) confirmed via source read that musyxTriggerVoiceAttack
    # is the only known writer of voice+0x0 nonzero anywhere in the
    # recompiled tree (musyxKeyOnVoice and isAudioSlotActive, the two
    # fallback candidates NEXT.md named, are now both refuted -- the former
    # never writes its argument at all, read-only; the latter is a pure
    # query) and that grepping for its guest address (0x8009231C) as a data
    # literal anywhere in the tree (the mechanism that resolved the
    # analogous s94-101 DMA-caller mystery) finds nothing, so no
    # table-driven indirect call is evidenced -- but a register-loaded jalr
    # from an as-yet-unfound caller remains structurally invisible to that
    # grep, same blind spot as before. This patch moves the chokepoint to
    # the function's OWN entry, which catches every call regardless of
    # path, direct or indirect, static or not-yet-found -- the same
    # "instrument the target, not the suspected caller" correction that
    # eventually solved the DMA-caller question at s101.
    def _voice_attack_entry_patch(m):
        return m.group(1) + (
            "    { // PATCH: musyxTriggerVoiceAttack own-entry diagnostic (s116) -- see fixup_game_funcs.py comment\n"
            "        static int s_voice_attack_entry_enabled = -1;\n"
            "        if (s_voice_attack_entry_enabled < 0) { const char* e = getenv(\"ROGUESQ_LOG_VOICE_ATTACK_ENTRY\"); s_voice_attack_entry_enabled = (e && e[0] && e[0] != '0') ? 1 : 0; }\n"
            "        if (s_voice_attack_entry_enabled) {\n"
            "            static int s_voice_attack_entry_n = 0;\n"
            "            if (s_voice_attack_entry_n < 32) {\n"
            "                fprintf(stderr, \"[voice-attack-entry] n=%d voiceIdx=0x%08X\\n\", s_voice_attack_entry_n, U32(ctx->r4));\n"
            "            }\n"
            "            s_voice_attack_entry_n++;\n"
            "        }\n"
            "    }\n"
        )
    # (scoped, s380 backport) target: musyxTriggerVoiceAttack (pattern anchors on
    # the function's own opening line, so the header itself is included in
    # the sliced region rather than starting at body_start).
    n = 0
    if p.name == "funcs_24.c":
        func_start_m = re.search(
            r"RECOMP_FUNC void musyxTriggerVoiceAttack\(uint8_t\* rdram, recomp_context\* ctx\) \{\n",
            text)
        if func_start_m:
            header_start = func_start_m.start()
            body_start = func_start_m.end()
            next_func_m = func_re.search(text, body_start)
            body_end = next_func_m.start() if next_func_m else len(text)
            region = text[header_start:body_end]

            new_region, n = re.subn(
                r"(RECOMP_FUNC void musyxTriggerVoiceAttack\(uint8_t\* rdram, recomp_context\* ctx\) \{\n"
                r"    uint64_t hi = 0, lo = 0, result = 0;\n"
                r"    int c1cs = 0;\n)",
                _voice_attack_entry_patch,
                region)
            if n:
                text = text[:header_start] + new_region + text[body_end:]
    if n:
        changed = True
        report.append(f"{p.name}: musyxTriggerVoiceAttack own-entry diagnostic patched x{n}")
        if "#include <stdio.h>" not in text:
            text = text.replace('#include "recomp.h"\n', '#include "recomp.h"\n#include <stdio.h>\n', 1)
        if "#include <stdlib.h>" not in text:
            text = text.replace('#include "recomp.h"\n', '#include "recomp.h"\n#include <stdlib.h>\n', 1)

    # musyxMixActiveVoices voice+0x0 gate-check diagnostic (s117, M3 item -1
    # continued): s116 closed both fallback +0x0-writer candidates
    # (musyxKeyOnVoice read-only, isAudioSlotActive pure query) and proved
    # with a same-run positive control that the one known nonzero-writer
    # (musyxTriggerVoiceAttack) never fires even while musyxRenderVoiceSamples
    # -- the function the +0x0 byte is supposed to gate -- genuinely runs
    # multiple times. That leaves a contradiction only a runtime value can
    # resolve: this patch logs the exact byte musyxMixActiveVoices reads at
    # `voice+0x0` (ctx->r2, already loaded via MEM_BU before the gating
    # `beq`), the voice-array base address it read from (ctx->r4), and the
    # loop index driving the scan (ctx->r16, the s0-backed counter set up
    # before the loop and untouched by the per-voice offset arithmetic that
    # clobbers r2/r3 inside the loop body) -- see fixup_game_funcs.py
    # comment for context.
    # s117 correction (same session, before first soak's cap was proven too
    # small): the original design capped at the first 64 checks total, but
    # each musyxMixActiveVoices call scans ~20 voices, so the cap exhausted
    # within the first few audio ticks -- a window that ends well under a
    # second into the run, nowhere near the ~140s mark where s116 proved
    # musyxRenderVoiceSamples (the function this byte gates) actually runs.
    # voicegate1's first soak confirmed this: 64/64 fires, byte=0x00 every
    # time, addresses sane and correctly strided (0x88 per voice, matching
    # the known struct) -- informative about addressing correctness, silent
    # about the moment that matters. Redesigned to decouple "capture a
    # nonzero value if one ever occurs" (uncapped counter, capped output)
    # from "prove logging survived to the end of the run" (a low-rate
    # heartbeat sampled every 5000th check, independent of value).
    def _voice_active_gate_patch(m):
        return m.group(1) + (
            "        { // PATCH: musyxMixActiveVoices voice+0x0 gate-check diagnostic (s117) -- see fixup_game_funcs.py comment\n"
            "            static int s_voice_active_gate_enabled = -1;\n"
            "            if (s_voice_active_gate_enabled < 0) { const char* e = getenv(\"ROGUESQ_LOG_VOICE_ACTIVE_GATE\"); s_voice_active_gate_enabled = (e && e[0] && e[0] != '0') ? 1 : 0; }\n"
            "            if (s_voice_active_gate_enabled) {\n"
            "                static long s_voice_active_gate_n = 0;\n"
            "                static int s_voice_active_gate_nz_n = 0;\n"
            "                unsigned char s_voice_active_gate_byte = (unsigned char)(U32(ctx->r2) & 0xFFu);\n"
            "                if (s_voice_active_gate_byte != 0 && s_voice_active_gate_nz_n < 64) {\n"
            "                    gpr s_vagn_base_reg = (gpr)(int32_t)(0X8015 << 16);\n"
            "                    uint32_t s_vagn_count = (uint32_t)MEM_HU(s_vagn_base_reg, -0X6900);\n"
            "                    uint32_t s_vagn_arraybase = (uint32_t)MEM_W(s_vagn_base_reg, -0X6908);\n"
            "                    fprintf(stderr, \"[voice-active-gate-nz] n=%ld idx=0x%08X base=0x%08X byte=0x%02X count=0x%04X arrayBase=0x%08X\\n\", s_voice_active_gate_n, U32(ctx->r16), U32(ctx->r4), (unsigned)s_voice_active_gate_byte, s_vagn_count, s_vagn_arraybase);\n"
            "                    fprintf(stderr, \"[voice-active-gate-nz]   bytes:\");\n"
            "                    for (int s_vagn_i = 0; s_vagn_i < 0x20; s_vagn_i++) {\n"
            "                        fprintf(stderr, \" %02X\", (unsigned)MEM_BU(ctx->r4, s_vagn_i));\n"
            "                    }\n"
            "                    fprintf(stderr, \"\\n\");\n"
            "                    s_voice_active_gate_nz_n++;\n"
            "                }\n"
            "                if (s_voice_active_gate_n % 5000 == 0) {\n"
            "                    fprintf(stderr, \"[voice-active-gate-hb] n=%ld idx=0x%08X base=0x%08X byte=0x%02X\\n\", s_voice_active_gate_n, U32(ctx->r16), U32(ctx->r4), (unsigned)s_voice_active_gate_byte);\n"
            "                }\n"
            "                s_voice_active_gate_n++;\n"
            "            }\n"
            "        }\n"
        )
    # (scoped, s380 backport) target: musyxMixActiveVoices
    n = 0
    if p.name == "funcs_24.c":
        func_start_m = re.search(
            r"RECOMP_FUNC void musyxMixActiveVoices\(uint8_t\* rdram, recomp_context\* ctx\) \{\n",
            text)
        if func_start_m:
            body_start = func_start_m.end()
            next_func_m = func_re.search(text, body_start)
            body_end = next_func_m.start() if next_func_m else len(text)
            body = text[body_start:body_end]

            new_body, n = re.subn(
                r"(    // 0x80090EC4: lbu         \$v0, 0x0\(\$a0\)\n"
                r"    ctx->r2 = MEM_BU\(ctx->r4, 0X0\);\n)",
                _voice_active_gate_patch,
                body)
            if n:
                text = text[:body_start] + new_body + text[body_end:]
    if n:
        changed = True
        report.append(f"{p.name}: musyxMixActiveVoices voice+0x0 gate-check diagnostic patched x{n}")
        if "#include <stdio.h>" not in text:
            text = text.replace('#include "recomp.h"\n', '#include "recomp.h"\n#include <stdio.h>\n', 1)
        if "#include <stdlib.h>" not in text:
            text = text.replace('#include "recomp.h"\n', '#include "recomp.h"\n#include <stdlib.h>\n', 1)

    # s147: fix the s145/s146-proven non-atomic race in allocateSongChannelArray.
    # The scan-bound global (-0x6900 off 0x80150000, 0x80149700) was written
    # with the NEW voiceCount at 0x8008F0C8-CC -- many instructions before the
    # new array pointer is published at 0x8008F0E4/0x8008F0EC -- letting a
    # concurrently-scanning musyxMixActiveVoices (audio runs off the VI-retrace
    # thread) observe the new, larger count against the still-old, smaller
    # array. s146 caught this live 4x in one soak. Fix: relocate the count
    # write to run AFTER both pointer stores. The original code also reloads
    # that same global right after writing it (0x8008F0D8-DC, into ctx->r3,
    # used later for a `voiceCount == 0` branch) -- that reload is moved down
    # WITH the write, immediately following it, so it still reads back exactly
    # what was just written and the branch's behavior is unchanged. Moving the
    # write alone (leaving the reload in its original spot) would have made
    # the reload read the *previous* call's stale count instead -- a real bug
    # the "ctx->r16 is never reassigned" register-safety check in NEXT.md's
    # plan did not by itself rule out, since the dependency here is through
    # memory (the -0x6900 global), not the register.
    # This patch runs BEFORE the s120/s146 diagnostic-insertion patches below
    # so their anchors (unmodified instruction text) still match; s120's print
    # keeps firing right after the pointer stores (now immediately before the
    # relocated write), and s146's print keeps firing right after the write
    # (now in its new position) -- both diagnostics stay meaningful without
    # any changes to their own patch code.
    _song_count_write_reorder_target = (
        "    // 0x8008F0C8: lui         $at, 0x8015\n"
        "    ctx->r1 = S32(0X8015 << 16);\n"
        "    // 0x8008F0CC: sh          $s0, -0x6900($at)\n"
        "    MEM_H(-0X6900, ctx->r1) = ctx->r16;\n"
        "    // 0x8008F0D0: jal         0x80001ACC\n"
        "    // 0x8008F0D4: addu        $a1, $zero, $zero\n"
        "    ctx->r5 = ADD32(0, 0);\n"
        "    rs_malloc(rdram, ctx);\n"
        "        goto after_0;\n"
        "    // 0x8008F0D4: addu        $a1, $zero, $zero\n"
        "    ctx->r5 = ADD32(0, 0);\n"
        "    after_0:\n"
        "    // 0x8008F0D8: lui         $v1, 0x8015\n"
        "    ctx->r3 = S32(0X8015 << 16);\n"
        "    // 0x8008F0DC: lhu         $v1, -0x6900($v1)\n"
        "    ctx->r3 = MEM_HU(ctx->r3, -0X6900);\n"
        "    // 0x8008F0E0: lui         $at, 0x8015\n"
        "    ctx->r1 = S32(0X8015 << 16);\n"
        "    // 0x8008F0E4: sw          $v0, -0x6904($at)\n"
        "    MEM_W(-0X6904, ctx->r1) = ctx->r2;\n"
        "    // 0x8008F0E8: lui         $at, 0x8015\n"
        "    ctx->r1 = S32(0X8015 << 16);\n"
        "    // 0x8008F0EC: sw          $v0, -0x6908($at)\n"
        "    MEM_W(-0X6908, ctx->r1) = ctx->r2;\n"
    )
    _song_count_write_reorder_replacement = (
        "    // 0x8008F0D0: jal         0x80001ACC\n"
        "    // 0x8008F0D4: addu        $a1, $zero, $zero\n"
        "    ctx->r5 = ADD32(0, 0);\n"
        "    rs_malloc(rdram, ctx);\n"
        "        goto after_0;\n"
        "    // 0x8008F0D4: addu        $a1, $zero, $zero\n"
        "    ctx->r5 = ADD32(0, 0);\n"
        "    after_0:\n"
        "    // 0x8008F0E0: lui         $at, 0x8015\n"
        "    ctx->r1 = S32(0X8015 << 16);\n"
        "    // 0x8008F0E4: sw          $v0, -0x6904($at)\n"
        "    MEM_W(-0X6904, ctx->r1) = ctx->r2;\n"
        "    // 0x8008F0E8: lui         $at, 0x8015\n"
        "    ctx->r1 = S32(0X8015 << 16);\n"
        "    // 0x8008F0EC: sw          $v0, -0x6908($at)\n"
        "    MEM_W(-0X6908, ctx->r1) = ctx->r2;\n"
        "    // PATCH: allocateSongChannelArray count-write/reload relocated here,\n"
        "    // after both pointer stores, to close the s145/s146 race window (s147).\n"
        "    // 0x8008F0C8: lui         $at, 0x8015\n"
        "    ctx->r1 = S32(0X8015 << 16);\n"
        "    // 0x8008F0CC: sh          $s0, -0x6900($at)\n"
        "    MEM_H(-0X6900, ctx->r1) = ctx->r16;\n"
        "    // 0x8008F0D8: lui         $v1, 0x8015\n"
        "    ctx->r3 = S32(0X8015 << 16);\n"
        "    // 0x8008F0DC: lhu         $v1, -0x6900($v1)\n"
        "    ctx->r3 = MEM_HU(ctx->r3, -0X6900);\n"
    )
    new, n = (text.replace(_song_count_write_reorder_target, _song_count_write_reorder_replacement, 1), text.count(_song_count_write_reorder_target)) \
        if p.name == "funcs_23.c" else (text, 0)
    if n:
        text = new
        changed = True
        report.append(f"{p.name}: allocateSongChannelArray count-write/reload reordered after pointer stores x{n}")

    # s120: allocateSongChannelArray stores the SAME rs_malloc pointer into
    # TWO globals (-0x6904 and -0x6908 off 0x80150000, i.e. 0x801496FC and
    # 0x801496F8) -- grep confirmed -0x6908 has exactly ONE store site
    # anywhere in the recompiled tree (this one). musyxMixActiveVoices
    # reloads -0x6908 fresh every scan (funcs_24.c ~0x80090E78) as its
    # voice-array base. shutdownAudioEngine frees -0x6904's pointer
    # (funcs_24.c ~0x80091E48) but never touches -0x6908 -- a candidate
    # dangling-alias mechanism for the s105-119 "voice+0x0/+0x34 corruption"
    # chase: after any shutdownAudioEngine call, -0x6908 points at freed
    # memory that a later, unrelated allocation (e.g. a texture-name table,
    # per s118's explo_tex/atpt_load find) can legally reuse. This patch
    # logs the alloc (voiceCount + pointer) so a soak can check whether
    # shutdownAudioEngine ever fires between an alloc and a corrupted
    # voice-active-gate read.
    def _song_array_alloc_patch(m):
        return m.group(1) + (
            "        { // PATCH: allocateSongChannelArray base-pointer alias diagnostic (s120)\n"
            "            static int s_song_alloc_enabled = -1;\n"
            "            if (s_song_alloc_enabled < 0) { const char* e = getenv(\"ROGUESQ_LOG_SONG_ARRAY_LIFECYCLE\"); s_song_alloc_enabled = (e && e[0] && e[0] != '0') ? 1 : 0; }\n"
            "            if (s_song_alloc_enabled) {\n"
            "                fprintf(stderr, \"[song-array-alloc] voiceCount=%u ptr=0x%08X\\n\", U32(ctx->r16), U32(ctx->r2));\n"
            "            }\n"
            "        }\n"
        )
    # (scoped, s380 backport) target: allocateSongChannelArray
    n = 0
    if p.name == "funcs_23.c":
        func_start_m = re.search(
            r"RECOMP_FUNC void allocateSongChannelArray\(uint8_t\* rdram, recomp_context\* ctx\) \{\n",
            text)
        if func_start_m:
            body_start = func_start_m.end()
            next_func_m = func_re.search(text, body_start)
            body_end = next_func_m.start() if next_func_m else len(text)
            body = text[body_start:body_end]

            new_body, n = re.subn(
                r"(    // 0x8008F0E8: lui         \$at, 0x8015\n"
                r"    ctx->r1 = S32\(0X8015 << 16\);\n"
                r"    // 0x8008F0EC: sw          \$v0, -0x6908\(\$at\)\n"
                r"    MEM_W\(-0X6908, ctx->r1\) = ctx->r2;\n)",
                _song_array_alloc_patch,
                body)
            if n:
                text = text[:body_start] + new_body + text[body_end:]
    if n:
        changed = True
        report.append(f"{p.name}: allocateSongChannelArray base-pointer alias diagnostic patched x{n}")
        if "#include <stdio.h>" not in text:
            text = text.replace('#include "recomp.h"\n', '#include "recomp.h"\n#include <stdio.h>\n', 1)
        if "#include <stdlib.h>" not in text:
            text = text.replace('#include "recomp.h"\n', '#include "recomp.h"\n#include <stdlib.h>\n', 1)

    # s146: allocateSongChannelArray writes the new voiceCount to the scan-
    # bound global (0x80149700, -0x6900 off 0x80150000) at 0x8008F0CC/CC --
    # BEFORE calling rs_malloc (0x8008F0D4) and BEFORE the pointer store /
    # [song-array-alloc] print at 0x8008F0E8-EC. s145 found circumstantial
    # evidence (log-line ordering only) that a concurrently-scanning
    # musyxMixActiveVoices can observe this new, larger count against the
    # still-old, smaller array mid-scan. This patch logs the count write
    # itself so a soak can check whether any [voice-active-gate-nz] (or a
    # corrupted read) lands, in log order, between this line and the
    # matching [song-array-alloc] line for the same voiceCount -- direct
    # proof of the race window, not inference from print ordering.
    def _song_count_write_early_patch(m):
        return m.group(1) + (
            "        { // PATCH: allocateSongChannelArray early count-write diagnostic (s146)\n"
            "            static int s_song_count_early_enabled = -1;\n"
            "            if (s_song_count_early_enabled < 0) { const char* e = getenv(\"ROGUESQ_LOG_SONG_ARRAY_LIFECYCLE\"); s_song_count_early_enabled = (e && e[0] && e[0] != '0') ? 1 : 0; }\n"
            "            if (s_song_count_early_enabled) {\n"
            "                fprintf(stderr, \"[song-count-write-early] voiceCount=%u\\n\", U32(ctx->r16));\n"
            "            }\n"
            "        }\n"
        )
    # (scoped, s380 backport) target: allocateSongChannelArray
    n = 0
    if p.name == "funcs_23.c":
        func_start_m = re.search(
            r"RECOMP_FUNC void allocateSongChannelArray\(uint8_t\* rdram, recomp_context\* ctx\) \{\n",
            text)
        if func_start_m:
            body_start = func_start_m.end()
            next_func_m = func_re.search(text, body_start)
            body_end = next_func_m.start() if next_func_m else len(text)
            body = text[body_start:body_end]

            new_body, n = re.subn(
                r"(    // 0x8008F0C8: lui         \$at, 0x8015\n"
                r"    ctx->r1 = S32\(0X8015 << 16\);\n"
                r"    // 0x8008F0CC: sh          \$s0, -0x6900\(\$at\)\n"
                r"    MEM_H\(-0X6900, ctx->r1\) = ctx->r16;\n)",
                _song_count_write_early_patch,
                body)
            if n:
                text = text[:body_start] + new_body + text[body_end:]
