    # s250: the other 2 of selectPostCrawlCraft's 3 candidates from the s249
    # sweep (funcs_30.c, 0x800CBDA8 and 0x800CBDE4) -- two near-identical
    # inlined doubly-linked-list "insert at tail" helpers reached via jal
    # from elsewhere but folded into this same RECOMP_FUNC block (no
    # RECOMP_FUNC boundary between them and selectPostCrawlCraft). Each
    # walks a list starting from an untrusted head field read out of a
    # struct (`MEM_W(ctx->r4, 0X20)` / `MEM_W(ctx->r4, 0X10)`) to find the
    # tail before appending a new node.
    #
    # Full-loop-body read (mandatory per this family's own s249 finding)
    # shows this loop is a DIFFERENT shape from selectPostCrawlCraft's own
    # fixed site, closer to renderUnlitMeshFaces's s219 GUARD/GUARD3 combo:
    # two back-to-back MEM_W(ctx->r3, 0X0) dereferences of the SAME
    # register, not two different aliased registers. Line 1 (the flagged
    # self-ref line, `ctx->r3 = MEM_W(ctx->r3, 0X0)`) dereferences the
    # incoming r3 (untrusted on iteration 2+: it's the previous iteration's
    # own unvalidated walk result). Line 2 (`ctx->r2 = MEM_W(ctx->r3, 0X0)`,
    # the peek-load) immediately dereferences the BRAND NEW r3 that line 1
    # just produced -- also unvalidated, same gap s219 named. A guard only
    # before line 1 (selectPostCrawlCraft's own template) would leave line
    # 2's peek exposed to whatever line 1 just read from untrusted memory.
    # So each site gets TWO guards this session: GUARD1 before the walk
    # (line 1), GUARD2 between the walk and the peek (line 2) -- both reuse
    # the same 0x80000000..0x80800000 lo-half / 0xFFFFFFFF hi-half RDRAM
    # sentinel check as every other guard in this family.
    #
    # Bail target: plain `return;`, not a goto to the loop's own natural
    # exit label. Verified by reading forward: the natural exit path (both
    # sites) falls through to `MEM_W(0X0, ctx->r3) = ctx->r5;` (write
    # new-node into old-tail's next field) then `MEM_W(0X4, ctx->r5) =
    # ctx->r3;` (write old-tail into new-node's prev field) before
    # returning -- both writes use the untrusted r3 as an address or value,
    # so jumping into that path on a bad r3 would just move the wild
    # dereference/store rather than avoid it. These are void-returning
    # insert helpers (no caller-visible error-code contract, unlike
    # selectPostCrawlCraft's own r2-based bail) -- silently abandoning the
    # insert on a corrupt list is the same "give up gracefully" contract
    # applied via the simplest bail this shape supports.
    def _make_selectpostcrawl_insguard_patch(site_addr, next_addr, tag):
        def _make(m):
            return (
                f"L_{site_addr}:\n"
                f"    {{ // PATCH: unguarded list-insert-walk loop-back guard, GUARD1 (s250, selectPostCrawlCraft helper {tag}) -- see fixup_game_funcs.py comment\n"
                f"        static int s_selectpostcrawl_insguard_{tag}1_enabled = -1;\n"
                f"        if (s_selectpostcrawl_insguard_{tag}1_enabled < 0) {{ const char* e = getenv(\"ROGUESQ_LOG_SELECTPOSTCRAWL_INSGUARD_{tag}1\"); s_selectpostcrawl_insguard_{tag}1_enabled = (e && e[0] && e[0] != '0') ? 1 : 0; }}\n"
                f"        uint32_t r3_lo = U32(ctx->r3);\n"
                f"        uint32_t r3_hi = (uint32_t)((uint64_t)ctx->r3 >> 32);\n"
                f"        if (r3_lo < 0x80000000u || r3_lo >= 0x80800000u || r3_hi != 0xFFFFFFFFu) {{\n"
                f"            if (s_selectpostcrawl_insguard_{tag}1_enabled) {{\n"
                f"                static int s_selectpostcrawl_insguard_{tag}1_n = 0;\n"
                f"                fprintf(stderr, \"[selectpostcrawl-insguard-{tag}1] n=%d site=0x{site_addr} bad_r3=0x%08X hi=0x%08X ra=0x%08X\\n\", s_selectpostcrawl_insguard_{tag}1_n, r3_lo, r3_hi, U32(ctx->r31));\n"
                f"                s_selectpostcrawl_insguard_{tag}1_n++;\n"
                f"            }}\n"
                f"            return;\n"
                f"        }}\n"
                f"    }}\n"
                f"    // 0x{site_addr}: lw          $v1, 0x0($v1)\n"
                f"    ctx->r3 = MEM_W(ctx->r3, 0X0);\n"
                f"    {{ // PATCH: unguarded peek-load on freshly-read (unvalidated) list-walk pointer, GUARD2 (s250, selectPostCrawlCraft helper {tag}) -- see fixup_game_funcs.py comment\n"
                f"        static int s_selectpostcrawl_insguard_{tag}2_enabled = -1;\n"
                f"        if (s_selectpostcrawl_insguard_{tag}2_enabled < 0) {{ const char* e = getenv(\"ROGUESQ_LOG_SELECTPOSTCRAWL_INSGUARD_{tag}2\"); s_selectpostcrawl_insguard_{tag}2_enabled = (e && e[0] && e[0] != '0') ? 1 : 0; }}\n"
                f"        uint32_t r3_lo = U32(ctx->r3);\n"
                f"        uint32_t r3_hi = (uint32_t)((uint64_t)ctx->r3 >> 32);\n"
                f"        if (r3_lo < 0x80000000u || r3_lo >= 0x80800000u || r3_hi != 0xFFFFFFFFu) {{\n"
                f"            if (s_selectpostcrawl_insguard_{tag}2_enabled) {{\n"
                f"                static int s_selectpostcrawl_insguard_{tag}2_n = 0;\n"
                f"                fprintf(stderr, \"[selectpostcrawl-insguard-{tag}2] n=%d site=0x{next_addr} bad_r3=0x%08X hi=0x%08X ra=0x%08X\\n\", s_selectpostcrawl_insguard_{tag}2_n, r3_lo, r3_hi, U32(ctx->r31));\n"
                f"                s_selectpostcrawl_insguard_{tag}2_n++;\n"
                f"            }}\n"
                f"            return;\n"
                f"        }}\n"
                f"    }}\n"
                f"    // 0x{next_addr}: lw          $v0, 0x0($v1)\n"
                f"    ctx->r2 = MEM_W(ctx->r3, 0X0);\n"
            )
        return _make

    _selectpostcrawl_insguard_sites = [
        ("800CBDA8", "800CBDAC", "A"),
        ("800CBDE4", "800CBDE8", "B"),
    ]
    # (scoped, s383 backport) target: selectPostCrawlCraft -- slice the
    # function body ONCE before the loop (these two inlined helpers are
