            "        uint32_t s_craft_type_idx = U32(ctx->r18);\n"
            "        if (s_craft_type_idx > 13u) {\n"
            "            if (s_load_craft_shadow_guard_enabled) {\n"
            "                static int s_load_craft_shadow_guard_n = 0;\n"
            "                fprintf(stderr, \"[load-craft-shadow-guard] n=%d arg_r4=0x%08X bad_idx=%u ra=0x%08X\\n\",\n"
