    # isAudioSlotActive (s166, 23rd crash class candidate, first seen s165's
    # audiodrain3 soak): SIGSEGV backtrace lands innermost in
    # waitForAnyAudioSlot itself (menuOverlayInit -> waitForAnyAudioSlot,
    # boot time, task #267, VI width still 640 -- earliest death in the
    # whole 23-class family). Source-read (per NEXT.md step 1) of
    # waitForAnyAudioSlot's two direct callees, tickMusyXIfActive
    # (funcs_23.c:6785, all-callee, no raw MEM_* deref) and
    # anyAudioSlotActive (funcs_23.c:8806, loops isAudioSlotActive per
    # channel index 0..chCount-1 off a fresh MEM_BU(0x80141AD0) channel
    # count each iteration -- no deref itself), found the actual unguarded
    # deref one level deeper in isAudioSlotActive (funcs_24.c:5788): a
    # base pointer loaded from the fixed global slot at 0x801496F8
    # (`lw $v0, -0x6908($v0)` off `lui $v0,0x8015`), combined with
    # `a0*136` (sll/addu/sll idiom) with ZERO null-check on the base
    # pointer before `lbu $v0, 0x0($v1)` -- textbook match for this
    # family's dominant shape (12th/14th/16th/21st classes: fixed-global
    # table pointer, indexed, dereferenced with no null/range check).
    # rs_free (funcs_0.c:3093, waitForAnyAudioSlot's other MEM_W-sourced
    # global-pointer callee) already null-checks its arg at entry -- ruled
    # out as a candidate, not guarded. Could not disassemble the native
    # +76-byte crash offset to confirm this is the exact faulting
    # instruction (nm/otool/lldb not on the Bash allowlist per NEXT.md);
    # no `[audio-drain-enter]` log line appears anywhere in the
    # audiodrain3 run.log despite ROGUESQ_LOG_AUDIO_DRAIN=1 being set,
    # consistent with (but not proof of) a crash this early, or simply
    # stderr buffering losing the line when the process died -- ambiguous,
    # not treated as evidence either way. isAudioSlotActive is frameless
    # (no $sp adjustment, no callee-saved spills), so a bare early
    # `return;` with a safe "not active" default (ctx->r2 = 0) is
    # ABI-correct -- no epilogue label needed, unlike every prior guard in
    # this family. Guest addresses 0x80092110/0x80092114 confirmed unique
    # across the whole RecompiledFuncs/ tree (not just funcs_24.c) via
    # grep before writing this patch.
    def _is_audio_slot_active_guard_patch(m):
        return m.group(1) + (
            "    { // PATCH: unguarded base-pointer deref guard (s166, 23rd crash class candidate) -- see fixup_game_funcs.py comment\n"
            "        static int s_is_audio_slot_active_guard_enabled = -1;\n"
            "        if (s_is_audio_slot_active_guard_enabled < 0) { const char* e = getenv(\"ROGUESQ_LOG_AUDIO_SLOT_ACTIVE_GUARD\"); s_is_audio_slot_active_guard_enabled = (e && e[0] && e[0] != '0') ? 1 : 0; }\n"
            "        uint32_t r2_lo = U32(ctx->r2);\n"
            "        if (r2_lo < 0x80000000u || r2_lo >= 0x80800000u) {\n"
            "            if (s_is_audio_slot_active_guard_enabled) {\n"
            "                static int s_is_audio_slot_active_guard_n = 0;\n"
            "                fprintf(stderr, \"[audio-slot-active-guard] n=%d arg_r4=0x%08X bad_r2=0x%08X ra=0x%08X\\n\",\n"
            "                        s_is_audio_slot_active_guard_n, U32(ctx->r4), r2_lo, U32(ctx->r31));\n"
            "                s_is_audio_slot_active_guard_n++;\n"
            "            }\n"
            "            ctx->r2 = 0;\n"
            "            return;\n"
            "        }\n"
            "    }\n"
        )
    # (scoped, s385 backport) target: isAudioSlotActive
    if p.name == "funcs_24.c":
        func_start_m = re.search(
            r"RECOMP_FUNC void isAudioSlotActive\(uint8_t\* rdram, recomp_context\* ctx\) \{\n",
            text)
        if func_start_m:
            body_start = func_start_m.end()
            next_func_m = func_re.search(text, body_start)
            body_end = next_func_m.start() if next_func_m else len(text)
            body = text[body_start:body_end]

            new_body, n = re.subn(
                r"(    // 0x80092110: addu        \$v1, \$v1, \$v0\n"
                r"    ctx->r3 = ADD32\(ctx->r3, ctx->r2\);\n)",
                _is_audio_slot_active_guard_patch,
                body)
            if n:
                text = text[:body_start] + new_body + text[body_end:]
                changed = True
                report.append(f"{p.name}: isAudioSlotActive base-pointer guard patched x{n}")
