    # checked against a raw line-count grep for both the lui and the reload
    # line, all three agreeing at 31) is sufficient, exactly like every
    # prior guard in this lineage.
    #
    # Unlike GENERIC_CACHE_GUARD/NODE_LIST_HEAD_GUARD's "substitute 0" (safe
    # ONLY because those sites deref at a literal 0 offset with no further
    # arithmetic, and 0 matches the game's own "empty list" semantics), 0 is
    # actively WRONG here: every downstream chain adds further index*stride
    # arithmetic and a positive offset before dereferencing, so 0 as a base
    # would produce a tiny, guaranteed-invalid address (e.g. ~0x2410) --
    # MORE certain to crash than leaving the original wild value alone.
    # Instead this guard substitutes 0x80000000 (the first byte of RDRAM,
    # always validly mapped) as the reload register's value when the raw
    # reload is outside [0x80000000, 0x80800000): any subsequent index*36+
    # offset arithmetic starting from a valid RDRAM base stays inside the
    # 8MB RDRAM window for any index a legitimate caller could plausibly
    # supply (up to ~233000 at this struct's 36-byte stride), consistent
    # with this lineage's scoping rule of only fixing THIS global's own
    # reload risk, not compound bugs in whatever computes the index.
    if p.name == "funcs_6.c":
        _texdata_table_guard_re = re.compile(
            r"    // (?P<addr1>0x[0-9A-Fa-f]+): lui         \$\w+, 0x8013\n"
            r"(?P<bc1i>    g_rs64_last_guest_pc = 0x[0-9A-Fa-f]+u;\n)?"
            r"    ctx->r(?P<rload>\d+) = S32\(0X8013 << 16\);\n"
            r"(?P<bc1>    g_rs64_last_guest_pc = 0x[0-9A-Fa-f]+u;\n)?"
            r"    // (?P<addr2>0x[0-9A-Fa-f]+): lw          \$\w+, -0x70F8\(\$\w+\)\n"
            r"(?P<bc2i>    g_rs64_last_guest_pc = 0x[0-9A-Fa-f]+u;\n)?"
            r"    ctx->r(?P=rload) = MEM_W\(ctx->r(?P=rload), -0X70F8\);\n"
            r"(?P<bc2>    g_rs64_last_guest_pc = 0x[0-9A-Fa-f]+u;\n)?"
        )

        def _texdata_table_guard_patch(m):
            rload = m.group('rload')
            addr1, addr2 = m.group('addr1'), m.group('addr2')
            bc1i, bc1 = m.group('bc1i') or '', m.group('bc1') or ''
            bc2i, bc2 = m.group('bc2i') or '', m.group('bc2') or ''
            return (
                f"    // {addr1}: lui         $reg, 0x8013\n"
                f"{bc1i}"
                f"    ctx->r{rload} = S32(0X8013 << 16);\n"
                f"{bc1}"
                f"    // {addr2}: lw          $reg, -0x70F8($reg)\n"
                f"{bc2i}"
                f"    ctx->r{rload} = MEM_W(ctx->r{rload}, -0X70F8);\n"
                f"    {{ // PATCH: unguarded texture-data-table base reload (s468, TEXDATA_TABLE_GUARD site={addr2}) -- see fixup_game_funcs.py comment\n"
                f"        static int s_texdata_table_guard_enabled = -1;\n"
                f'        if (s_texdata_table_guard_enabled < 0) {{ const char* e = getenv("ROGUESQ_LOG_TEXDATA_TABLE_GUARD"); s_texdata_table_guard_enabled = (e && e[0] && e[0] != \'0\') ? 1 : 0; }}\n'
                f"        uint32_t texdata_table_base_{addr2} = U32(ctx->r{rload});\n"
                f"        if (texdata_table_base_{addr2} < 0x80000000u || texdata_table_base_{addr2} >= 0x80800000u) {{\n"
                f"            if (s_texdata_table_guard_enabled) {{\n"
                f"                static int s_texdata_table_guard_n = 0;\n"
                f'                fprintf(stderr, "[texdata-table-guard] site={addr2} n=%d bad_base=0x%08X ra=0x%08X\\n", s_texdata_table_guard_n, texdata_table_base_{addr2}, U32(ctx->r31));\n'
                f"                s_texdata_table_guard_n++;\n"
                f"            }}\n"
                f"            ctx->r{rload} = (gpr)(int32_t)0x80000000u; // substitute a validly-mapped RDRAM base -- 0 would put downstream index*stride+offset arithmetic at a guaranteed-invalid tiny address\n"
                f"        }}\n"
                f"    }}\n"
                f"{bc2}"
            )

        text, n_texdata_table_guard = _texdata_table_guard_re.subn(_texdata_table_guard_patch, text)
        if n_texdata_table_guard:
            if "#include <stdio.h>" not in text:
                text = text.replace('#include "recomp.h"\n', '#include "recomp.h"\n#include <stdio.h>\n', 1)
            if "#include <stdlib.h>" not in text:
                text = text.replace('#include "recomp.h"\n', '#include "recomp.h"\n#include <stdlib.h>\n', 1)
            changed = True
            report.append(f"{p.name}: texture-data-table base reload guard (TEXDATA_TABLE_GUARD) patched x{n_texdata_table_guard}")

    # s470, TEXDATA_PTR_ARRAY_GUARD: item -303, the s465 scan's promoted
    # next candidate (hi16=0x8013, offset=-0x7104, funcs_6.c ONLY, same file
    # as item -301's TEXDATA_TABLE_GUARD at -0x70F8, 12 bytes away -- a
    # plausible sibling texture-management global). scratch_s470_shapecheck_
    # generic output (N64Recomp repo, untracked run of scratch_s468_
    # shapecheck_generic.py 8013 -7104) found 9 distinct downstream
    # instruction-chain shapes across the 29 sites, split roughly into two
    # risk patterns, both confirmed by direct reads of funcs_6.c (not just
    # the tool's truncated window):
