def _s4648_funcs27_s4332_s4339(tree):
    """Backport live-only s4332 (no source) and apply s4339 after it.

    In the fixup's loop the s4339 block runs before the s4323 caller witness it
    needs, so both are applied here, after the loop. Diagnostic only."""
    p = pathlib.Path(tree) / "funcs_27.c"
    text = p.read_text()
    msgs = []
    seq = "    rs64_filter_voice_sequence_probe(\"caller\", 0x8009D740u);\n"
    caller = ('    rs64_filter_voice_caller_probe("decodeAndFillVoiceBlock", 0x8009C88Cu, U32(ctx->r4), '
              'U32(ctx->r5), U32(ctx->r6), U32(ctx->r7)); /* PATCH: s4323 filter caller witness */\n')
    d4332 = ("    rs64_filter_voice_c88c_descriptor_probe(U32(ctx->r4), U32(ctx->r5), U32(ctx->r6), "
             "U32(ctx->r7)); /* PATCH: s4332 C88C descriptor witness */\n")
    d4339 = ("    rs64_filter_voice_c88c_field_probe(rdram, U32(ctx->r16), U32(ctx->r17), "
             "U32(ctx->r2)); /* PATCH: s4339 C88C source/branch witness */\n")
    if "PATCH: s4332 C88C descriptor witness" not in text:
        anchor = caller + seq if text.count(caller + seq) == 1 else caller
        if text.count(anchor) != 1:
            raise RuntimeError(f"s4648 s4332 anchor count={text.count(anchor)}")
        text = text.replace(anchor, anchor + d4332, 1)
        decl = "extern void rs64_filter_voice_c88c_descriptor_probe(uint32_t a0, uint32_t a1, uint32_t a2, uint32_t a3);\n"
        if decl not in text:
            text = text.replace('#include "funcs.h"\n', '#include "funcs.h"\n' + decl, 1)
        msgs.append("funcs_27.c: s4332 C88C descriptor witness (s4648 backport)")
    if "PATCH: s4339 C88C source/branch witness" not in text:
        if text.count(d4332) != 1:
            raise RuntimeError(f"s4648 s4339 anchor count={text.count(d4332)}")
        text = text.replace(d4332, d4332 + d4339, 1)
        msgs.append("funcs_27.c: s4339 C88C source/branch witness (deferred from loop)")
    p.write_text(text)
    return msgs


# Live tree carries the pre-s4204 s2190 writer-parity form: six targets,
# 640-wide only, no value column, and every scalar call passes 0u. The current
# fixup emits a seven-target helper and valued calls. Diagnostic either way
# (the helper only logs; it forwards `value` to logging-only watchers), but the
# live form is what later anchors (s3290/s3300/s3302/s4140) and the live tree
# expect, so reproduce it.
_S2190_LIVE_HELPER = r"""/* PATCH: s2190 m5 writer parity helper */
static void rs64_m5_writer_parity(char width, uint32_t pc,
                                   uint32_t addr, uint32_t value) {
    static int enabled = -1;
    static int control = 0;
    static uint32_t seen_pc[6][2][256];
    static unsigned short seen_n[6][2];
    static unsigned long total[6][2];
    static const uint32_t targets[6] = {
        0x25A580u, 0x0CA748u, 0x0C7B0Cu,
        0x165E40u, 0x0CDB58u, 0x2231ECu
    };
    unsigned width_n;
    unsigned origin_n;
    unsigned phase;
    unsigned bucket;
    unsigned span;
    unsigned adjust;
    unsigned i;
    unsigned off;
    uint32_t phys;
    uint32_t end;
    extern uint32_t rs64_phase_ord(void);
    extern uint32_t rs64_vi_committed_width(void);
    extern uint32_t rs64_vi_committed_origin(void);
    if (enabled < 0) {
        const char* e = getenv("ROGUESQ_LOG_M5_WRITER_PARITY");
        const char* all = getenv("ROGUESQ_LOG_ALL");
        enabled = ((e && e[0] && e[0] != '0') ||
                   (all && all[0] && all[0] != '0')) ? 1 : 0;
    }
    {
        extern void rs64_m5_route_value_writer(char width, uint32_t pc,
                                                uint32_t addr,
                                                uint32_t value);
        rs64_m5_route_value_writer(width, pc, addr, value);
    }
    if (!enabled) return;
    if (addr == 0x801E8710u) {
        unsigned source_width = rs64_vi_committed_width();
        unsigned source_origin = rs64_vi_committed_origin();
        if (source_width == 1024u &&
            (source_origin == 0x00790400u || source_origin == 0x00790800u)) {
            static unsigned source_rows = 0;
            if (source_rows < 1024u) {
                fprintf(stderr,
                        "[m5-source-writer] ordinal=%u phase=%u width=%u origin=0x%08X pc=0x%08X value=0x%08X\n",
                        source_rows++, rs64_phase_ord(), source_width,
                        source_origin, pc, value);
                fflush(stderr);
            }
        }
    }
    width_n = rs64_vi_committed_width();
    if (width_n != 640u) return;
    origin_n = rs64_vi_committed_origin();
    if (origin_n == 0x00696100u) bucket = 0u;
    else if (origin_n == 0x00696600u) bucket = 1u;
    else return;
    phase = rs64_phase_ord();
    if (!control) {
        fprintf(stderr, "[m5-writer-parity-control] phase=%u width=%u origin=0x%08X pc=0x%08X\n",
                phase, width_n, origin_n, pc);
        fflush(stderr);
        control = 1;
    }
    if (width == 'D') {
        span = 8u;
        adjust = 0u;
    } else {
        span = width == 'B' ? 1u : (width == 'H' ? 2u : 4u);
        adjust = width == 'B' ? 3u : (width == 'H' ? 2u : 0u);
    }
    (void)value;
    for (off = 0u; off < span; off += 4u) {
        phys = ((addr + off) ^ (off == 0u ? adjust : 0u)) - 0x80000000u;
        end = phys + ((width == 'D') ? 4u : span);
        for (i = 0u; i < 6u; ++i) {
            unsigned j;
            if (phys > targets[i] || end <= targets[i]) continue;
            ++total[i][bucket];
            for (j = 0u; j < seen_n[i][bucket]; ++j) {
                if (seen_pc[i][bucket][j] == pc) break;
            }
            if (j == seen_n[i][bucket] && seen_n[i][bucket] < 256u) {
                seen_pc[i][bucket][j] = pc;
                ++seen_n[i][bucket];
                fprintf(stderr, "[m5-writer-parity] target=%u phys=0x%06X pc=0x%08X width=%c phase=%u origin=0x%08X total=%lu unique=%u\n",
                        i + 1u, targets[i], pc, width, phase, origin_n,
                        total[i][bucket], seen_n[i][bucket]);
                fflush(stderr);
            }
        }
    }
}
"""
_S2190_HDR = "/* PATCH: s2190 m5 writer parity helper */"
def _s4648_s2190_live_compat(tree):
    n_files = n_lines = 0
    for p in sorted(pathlib.Path(tree).glob("funcs_*.c")):
        text = p.read_text()
        new, pairs = _s4648_s2190_zero(text)
        i = new.find(_S2190_HDR)
        if i >= 0:
            j = new.find("\n}\n", i)
            new = new[:i] + _S2190_LIVE_HELPER + new[j + 3:]
        if new != text:
            p.write_text(new)
            n_files += 1
            n_lines += sum(z != o for z, o in pairs)
    return [f"s2190 live-compat: {n_files} files, {n_lines} scalar calls -> 0u, helper -> live six-target form"]


def _s4648_s4597(tree):
    """s4597 rs_strncpy target-store census (diagnostic). The tools script's
    4-space anchor is a substring of its 8-space anchor, so it never applies to
    a fresh tree; reproduce the live result with exact anchors."""
    p = pathlib.Path(tree) / "funcs_2.c"
    s = p.read_text()
    if "PATCH: s4597 entry control" in s:
        return ["s4597 already present"]
    s = s.replace('#include "funcs.h"\n', '#include "funcs.h"\nextern void rs64_s4597_target_store(char, uint32_t, uint32_t, uint32_t);\n', 1)
    entry = "RECOMP_FUNC void rs_strncpy(uint8_t* rdram, recomp_context* ctx) {\n"
    if s.count(entry) != 1:
        raise RuntimeError(f"s4597 rs_strncpy anchor count={s.count(entry)}")
    s = s.replace(entry, entry + "    rs64_s4597_target_store('E', 0x80007640u, 0xFFFFFFFFu, 0u); /* PATCH: s4597 entry control */\n", 1)
    call = "rs64_s4597_target_store('B', 0x80007670u, U32(ADD32(ctx->r7, 0X0)), U32(ctx->r3)); /* PATCH: s4597 */\n"
    out, n = [], 0
    for line in s.splitlines(True):
        out.append(line)
        if line.strip() == "// 0x80007670: sb          $v1, 0x0($a3)":
            out.append(line[:len(line) - len(line.lstrip())] + call)
            n += 1
    if n != 2:
        raise RuntimeError(f"s4597 store sites={n} (expected 2)")
    p.write_text("".join(out))
    return ["funcs_2.c: s4597 entry + 2 store sites (s4648 backport)"]


